// Package cmakegen renders the CMake files cppm produces.
//
// Two categories, and the distinction is load-bearing:
//
//   - User-owned: CMakeLists.txt is written once by `cppm init` and never
//     rewritten. The user may edit it freely.
//   - cppm-owned: .cppm/generated/cppm_dependencies.cmake is regenerated on
//     every sync and carries a do-not-edit banner.
//
// The generated file's public interface is a compatibility surface cppm cannot
// migrate later, because it lives inside a file cppm does not own. It is
// deliberately four names: the include path, cppm_link_dependencies(),
// CPPM_TARGETS_<dep> and CPPM_DEPENDENCIES. Everything else is prefixed _cppm_
// to mark it private. See docs/architecture.md section 5.
package cmakegen

import (
	"encoding/json"
	"fmt"
	"sort"
	"strings"

	"cppm/internal/lockfile"
	"cppm/internal/manifest"
)

// DoNotEditBanner heads every generated file.
const DoNotEditBanner = "# Generated by cppm. DO NOT EDIT -- your changes will be overwritten.\n# Regenerate with: cppm sync\n"

// CMakeLists renders the user-owned top-level CMakeLists.txt.
func CMakeLists(m *manifest.Manifest) string {
	var b strings.Builder

	fmt.Fprintf(&b, "cmake_minimum_required(VERSION %s)\n\n", m.CMake.Minimum)
	fmt.Fprintf(&b, "project(%s\n    VERSION %s\n    LANGUAGES CXX\n)\n\n", m.Name, m.Version)

	b.WriteString("# C++ standard.\n")
	b.WriteString("#\n")
	b.WriteString("# CMAKE_CXX_EXTENSIONS is OFF on purpose. It defaults to ON, which compiles\n")
	b.WriteString("# your code as gnu++NN and leaves dependencies on mixed dialects -- code that\n")
	b.WriteString("# builds under GCC and Clang and then fails under MSVC.\n")
	fmt.Fprintf(&b, "set(CMAKE_CXX_STANDARD %d)\n", m.CXX.Standard)
	fmt.Fprintf(&b, "set(CMAKE_CXX_STANDARD_REQUIRED %s)\n", onOff(m.CXX.Required))
	fmt.Fprintf(&b, "set(CMAKE_CXX_EXTENSIONS %s)\n\n", onOff(m.CXX.Extensions))

	b.WriteString("# cppm-managed dependencies. Declared in cppm.json, pinned in cppm.lock.\n")
	b.WriteString("# This include must come before your targets so they can link against them.\n")
	b.WriteString("include(\"${CMAKE_CURRENT_SOURCE_DIR}/.cppm/generated/cppm_dependencies.cmake\")\n\n")

	for _, name := range m.TargetNames() {
		t := m.Targets[name]
		switch t.Kind {
		case manifest.KindLibrary:
			fmt.Fprintf(&b, "add_library(%s\n", name)
		default:
			fmt.Fprintf(&b, "add_executable(%s\n", name)
		}
		for _, s := range t.Sources {
			fmt.Fprintf(&b, "    %s\n", s)
		}
		b.WriteString(")\n\n")

		fmt.Fprintf(&b, "target_include_directories(%s PRIVATE include)\n\n", name)

		b.WriteString("# Links the dependencies from cppm.json. Replace this with your own\n")
		b.WriteString("# target_link_libraries() calls whenever you need finer control --\n")
		b.WriteString("# cppm never rewrites this file.\n")
		if len(t.Dependencies) > 0 {
			fmt.Fprintf(&b, "cppm_link_dependencies(%s %s)\n", name, strings.Join(t.Dependencies, " "))
		} else {
			fmt.Fprintf(&b, "cppm_link_dependencies(%s)\n", name)
		}
	}
	return b.String()
}

// MainCPP renders a hello-world that proves the toolchain works end to end.
func MainCPP(projectName string) string {
	return fmt.Sprintf(`#include <iostream>

int main()
{
    std::cout << "Hello from %s\n";
    return 0;
}
`, projectName)
}

// GitIgnore renders the .gitignore for a new project.
//
// cppm.json and cppm.lock are deliberately NOT ignored: the manifest is intent
// and the lock is reproducibility, so both belong in version control.
func GitIgnore() string {
	return `# cppm-owned: generated files and downloaded sources
.cppm/

# Build output
build/

# Editor and OS noise
.vscode/
.idea/
.DS_Store
compile_commands.json
`
}

// Dependencies renders .cppm/generated/cppm_dependencies.cmake from the lock.
func Dependencies(l *lockfile.Lock, cppmVersion string) string {
	var b strings.Builder

	b.WriteString(DoNotEditBanner)
	fmt.Fprintf(&b, "#\n# cppm %s\n", cppmVersion)
	fmt.Fprintf(&b, "# %d dependency(ies)\n\n", len(l.Packages))

	b.WriteString("include_guard(GLOBAL)\n")
	b.WriteString("include(FetchContent)\n\n")

	b.WriteString("# Keyword availability differs by CMake version, so emit only what is\n")
	b.WriteString("# supported: SYSTEM is 3.25+, EXCLUDE_FROM_ALL is 3.28+. Both keep a\n")
	b.WriteString("# dependency's warnings, install rules and spare targets out of your build.\n")
	b.WriteString("set(_cppm_fc_keywords \"\")\n")
	b.WriteString("if(CMAKE_VERSION VERSION_GREATER_EQUAL 3.25)\n")
	b.WriteString("    list(APPEND _cppm_fc_keywords SYSTEM)\n")
	b.WriteString("endif()\n")
	b.WriteString("if(CMAKE_VERSION VERSION_GREATER_EQUAL 3.28)\n")
	b.WriteString("    list(APPEND _cppm_fc_keywords EXCLUDE_FROM_ALL)\n")
	b.WriteString("endif()\n\n")

	b.WriteString("set(CPPM_DEPENDENCIES \"\")\n\n")

	var fetchNames []string

	for _, p := range l.Packages {
		fmt.Fprintf(&b, "# ---------------------------------------------------------------------------\n")
		if p.Requested != "" {
			fmt.Fprintf(&b, "# %s @ %s\n", p.Name, p.Requested)
		} else {
			fmt.Fprintf(&b, "# %s\n", p.Name)
		}
		fmt.Fprintf(&b, "# ---------------------------------------------------------------------------\n")

		// Cache options must be set BEFORE the dependency is made available,
		// which is the only point at which they take effect. Without them every
		// dependency builds its own tests, examples and benchmarks.
		for _, k := range sortedKeys(p.Options) {
			fmt.Fprintf(&b, "set(%s %s CACHE STRING \"\" FORCE)\n", k, cmakeQuote(p.Options[k]))
		}

		switch p.Source {
		case manifest.SourcePath:
			fmt.Fprintf(&b, "add_subdirectory(%s \"${CMAKE_BINARY_DIR}/_cppm/%s\" EXCLUDE_FROM_ALL)\n",
				cmakeQuote(p.Path), p.Name)
		default:
			fmt.Fprintf(&b, "FetchContent_Declare(%s\n", p.Name)
			fmt.Fprintf(&b, "    GIT_REPOSITORY %s\n", cmakeQuote(p.URL))
			fmt.Fprintf(&b, "    GIT_TAG        %s\n", p.Commit)
			if p.ShallowOK == nil || *p.ShallowOK {
				b.WriteString("    GIT_SHALLOW    ON\n")
			}
			b.WriteString("    GIT_PROGRESS   ON\n")
			b.WriteString("    ${_cppm_fc_keywords}\n")
			b.WriteString(")\n")
			fetchNames = append(fetchNames, p.Name)
		}

		if len(p.Targets) > 0 {
			fmt.Fprintf(&b, "set(CPPM_TARGETS_%s %s)\n", p.Name, strings.Join(p.Targets, " "))
		} else {
			fmt.Fprintf(&b, "set(CPPM_TARGETS_%s \"\")\n", p.Name)
		}
		fmt.Fprintf(&b, "list(APPEND CPPM_DEPENDENCIES %s)\n\n", p.Name)
	}

	if len(fetchNames) > 0 {
		b.WriteString("# A single MakeAvailable call keeps resolution order predictable.\n")
		fmt.Fprintf(&b, "FetchContent_MakeAvailable(%s)\n\n", strings.Join(fetchNames, " "))
	}

	// Verification. Because target names are partly inferred, a clear failure
	// here is a primary user experience rather than an edge case.
	b.WriteString(`# ---------------------------------------------------------------------------
# Verify that every dependency really provides the target cppm expects.
# ---------------------------------------------------------------------------
foreach(_cppm_dep IN LISTS CPPM_DEPENDENCIES)
    foreach(_cppm_target IN LISTS CPPM_TARGETS_${_cppm_dep})
        if(NOT TARGET ${_cppm_target})
            message(FATAL_ERROR
                "cppm: dependency '${_cppm_dep}' does not provide target '${_cppm_target}'.\n"
                "cppm could not determine the right target name. Either pin it in cppm.json:\n"
                "    \"${_cppm_dep}\": { ..., \"targets\": [\"<real::target>\"] }\n"
                "or link it yourself in CMakeLists.txt -- cppm will not overwrite your edits.\n"
                "Run 'cppm info ${_cppm_dep}' to see the candidates that were considered.")
        endif()
    endforeach()
endforeach()

# ---------------------------------------------------------------------------
# cppm_link_dependencies(<target> [<dep>...])
#
# With no dependency names, links every dependency in cppm.json. With names,
# links only those. For anything finer, use CPPM_TARGETS_<dep> directly in your
# own target_link_libraries() call.
# ---------------------------------------------------------------------------
function(cppm_link_dependencies _cppm_link_target)
    if(NOT TARGET ${_cppm_link_target})
        message(FATAL_ERROR "cppm_link_dependencies: '${_cppm_link_target}' is not a target")
    endif()

    set(_cppm_wanted ${ARGN})
    if(NOT _cppm_wanted)
        set(_cppm_wanted ${CPPM_DEPENDENCIES})
    endif()

    foreach(_cppm_dep IN LISTS _cppm_wanted)
        if(NOT DEFINED CPPM_TARGETS_${_cppm_dep})
            message(FATAL_ERROR
                "cppm_link_dependencies: unknown dependency '${_cppm_dep}'.\n"
                "Known dependencies: ${CPPM_DEPENDENCIES}")
        endif()
        foreach(_cppm_target IN LISTS CPPM_TARGETS_${_cppm_dep})
            target_link_libraries(${_cppm_link_target} PRIVATE ${_cppm_target})
        endforeach()
    endforeach()
endfunction()
`)
	return b.String()
}

// preset mirrors the subset of CMakePresets.json that cppm generates.
type preset struct {
	Name           string            `json:"name"`
	DisplayName    string            `json:"displayName,omitempty"`
	Generator      string            `json:"generator,omitempty"`
	BinaryDir      string            `json:"binaryDir,omitempty"`
	CacheVariables map[string]string `json:"cacheVariables,omitempty"`
}

type buildPreset struct {
	Name            string `json:"name"`
	ConfigurePreset string `json:"configurePreset"`
}

type presetsFile struct {
	Version              int            `json:"version"`
	CMakeMinimumRequired map[string]int `json:"cmakeMinimumRequired"`
	ConfigurePresets     []preset       `json:"configurePresets"`
	BuildPresets         []buildPreset  `json:"buildPresets"`
}

// Presets renders CMakePresets.json.
//
// Build commands wrap these rather than reimplementing CMake invocation, which
// means VS Code CMake Tools, CLion and Visual Studio read the same configuration
// the CLI uses.
func Presets(m *manifest.Manifest, generator string) (string, error) {
	mk := func(name, display, buildType string) preset {
		return preset{
			Name:        name,
			DisplayName: display,
			Generator:   generator,
			BinaryDir:   "${sourceDir}/build/" + name,
			CacheVariables: map[string]string{
				"CMAKE_BUILD_TYPE":              buildType,
				"CMAKE_EXPORT_COMPILE_COMMANDS": "ON",
			},
		}
	}
	major, minor, patch := parseVersionTriple(m.CMake.Minimum)
	pf := presetsFile{
		Version:              3,
		CMakeMinimumRequired: map[string]int{"major": major, "minor": minor, "patch": patch},
		ConfigurePresets: []preset{
			mk("debug", "Debug", "Debug"),
			mk("release", "Release", "RelWithDebInfo"),
		},
		BuildPresets: []buildPreset{
			{Name: "debug", ConfigurePreset: "debug"},
			{Name: "release", ConfigurePreset: "release"},
		},
	}
	b, err := json.MarshalIndent(pf, "", "  ")
	if err != nil {
		return "", err
	}
	return string(b) + "\n", nil
}

func onOff(v bool) string {
	if v {
		return "ON"
	}
	return "OFF"
}

// cmakeQuote wraps a value in double quotes, escaping what CMake treats
// specially. Values originate from a manifest, so they are never trusted to be
// free of quotes or backslashes.
func cmakeQuote(s string) string {
	r := strings.NewReplacer(`\`, `\\`, `"`, `\"`, `$`, `\$`)
	return `"` + r.Replace(s) + `"`
}

func sortedKeys(m map[string]string) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

func parseVersionTriple(s string) (int, int, int) {
	var major, minor, patch int
	n, _ := fmt.Sscanf(s, "%d.%d.%d", &major, &minor, &patch)
	if n < 2 {
		return 3, 24, 0
	}
	return major, minor, patch
}
